#nullable enable

using Microsoft.Extensions.DependencyInjection;
using Allocation.Contracts;
using Allocation.Slices.Allocation;
using Shouldly;
using Wolverine;
using Xunit;

namespace Allocation.IntegrationTests.Slices.Allocation;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: automation. Status: ready.
/// LIVE, so every test here must pass.
///
/// THE COMPENSATING HALF. Its rules read like bookkeeping and are not: a duplicate release hands the same
/// unit back twice, so the pool grows past its own capacity — the limited resource stops being limited
/// through the very mechanism meant to protect it.
/// </summary>
public sealed class ReleaseSlotTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private const string Reason = "TheWorkRefused";

    private static string SlotStream(int n) => ReleaseSlotState.StreamKey(SeedData.PoolId, n);
    private static string GrantStream(Guid grantId) => IssueGrantState.StreamKey(grantId.ToString());

    private async Task<SliceOutcome> Release(int slot = 1, Guid? grantId = null)
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        return await bus.InvokeAsync<SliceOutcome>(
            new ReleaseSlot(SeedData.PoolId, slot, grantId ?? SeedData.RefusedGrant, Reason));
    }

    // A refused grant gives its slot back
    //   GIVEN Slot Reserved(slotNumber=1), Grant Refused(slotNumber=1)
    //   WHEN  ReleaseSlot(slotNumber=1)
    //   THEN  Slot Released(slotNumber=1)
    [Fact]
    public async Task ARefusedGrantGivesItsSlotBack()
    {
        await Given(SlotStream(1),
            new SlotReserved(SeedData.PoolId, 1, SeedData.RefusedGrant, SeedData.SeededAt));
        await Given(GrantStream(SeedData.RefusedGrant),
            new GrantRefused(SeedData.RefusedGrant, SeedData.PoolId, 1, Reason, SeedData.SeededAt));

        (await Release()).Accepted.ShouldBeTrue();

        var events = await EventsFor(SlotStream(1));
        events.Length.ShouldBe(2);
        var released = events[1].ShouldBeOfType<SlotReleased>();
        released.SlotNumber.ShouldBe(1);
        released.Reason.ShouldBe(Reason);
    }

    // A slot already given back is not released twice
    //   GIVEN Slot Reserved(slotNumber=1), Grant Refused(slotNumber=1), Slot Released(slotNumber=1)
    //   WHEN  ReleaseSlot(slotNumber=1)
    //   THEN  error: AlreadyReleased
    [Fact]
    public async Task ASlotAlreadyGivenBackIsNotReleasedTwice()
    {
        await Given(SlotStream(1),
            new SlotReserved(SeedData.PoolId, 1, SeedData.RefusedGrant, SeedData.SeededAt),
            new SlotReleased(SeedData.PoolId, 1, SeedData.RefusedGrant, Reason, SeedData.SeededAt));
        await Given(GrantStream(SeedData.RefusedGrant),
            new GrantRefused(SeedData.RefusedGrant, SeedData.PoolId, 1, Reason, SeedData.SeededAt));

        var outcome = await Release();

        outcome.Accepted.ShouldBeFalse();
        outcome.Error.ShouldBe(ReleaseSlotHandler.AlreadyReleased);
        (await EventsFor(SlotStream(1))).Length.ShouldBe(2);
    }
}
